{
  "primary_meaning": "A complete cycle of time patterned on the six days of creation plus the seventh-day Sabbath rest, symbolizing divine order, work completed, and sacred rest",
  "primary_basis": [
    "Genesis 1:1–2:3",
    "Exodus 20:8–11",
    "Exodus 31:12–17"
  ],
  "alternatives": [
    {
      "meaning": "In apocalyptic prophecy a 'week' (Hebrew shabua) functions as a heptad of years rather than calendar days",
      "basis": [
        "Daniel 9:24–27",
        "common evangelical and historicist readings of the seventy weeks"
      ],
      "prominence": "common"
    },
    {
      "meaning": "The liturgical 'Holy Week' or Passion Week commemorating the final days of Jesus' earthly ministry",
      "basis": [
        "the Gospel passion narratives (esp. Matthew 21–28; Mark 11–16; Luke 19–24; John 12–20)",
        "historic Christian calendar practice"
      ],
      "prominence": "common"
    },
    {
      "meaning": "A general emblem of completeness or fullness (tied to the biblical significance of the number seven)",
      "basis": [
        "recurrent use of seven throughout Scripture (e.g., seven days, seven churches, seven seals)"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "The creation-week pattern is the foundational and most widely taught symbolic sense across historic Christian tradition; the prophetic-year and liturgical uses are context-specific but well-established secondary readings."
}
